  ,'staff-allowances':{route:'/settings/awards',before:async demo=>automaticAward(demo,demo.staff.id),focus:{selector:'.user-employment-allowances',text:'Allowances staff onboarding uniform laundry cold vehicle travel meals reimbursements'},act:async({frame})=>{const card=frame.locator('.award-location-card').filter({hasText:'Harbour Demo'});await card.locator('details').last().locator('summary').click();await card.locator('.award-team-list li').filter({hasText:'Demo Team Member'}).getByRole('button',{name:'Edit details',exact:true}).click();await frame.locator('.user-employment-allowances summary').click();for(const id of ['laundry','delivery','meal'])await frame.locator('[data-staff-allowance='+id+']').check();await frame.locator('.user-employment-allowances').scrollIntoViewIfNeeded();}},
